// Phase 4: Intent Architect Agent
// 사용자 의도를 분해하여 구조화된 작업으로 변환

use crate::phase4::agent_framework::*;

// ===== Intent Type (Phase 2 확장) =====

enum IntentType {
    Compute,
    Transform,
    Filter,
    Aggregate,
    IO,
    Control,
    Validate,
    Format,
    Unknown
}

impl IntentType {
    fn to_string(&self) -> String {
        match self {
            IntentType::Compute => "Compute".to_string(),
            IntentType::Transform => "Transform".to_string(),
            IntentType::Filter => "Filter".to_string(),
            IntentType::Aggregate => "Aggregate".to_string(),
            IntentType::IO => "IO".to_string(),
            IntentType::Control => "Control".to_string(),
            IntentType::Validate => "Validate".to_string(),
            IntentType::Format => "Format".to_string(),
            IntentType::Unknown => "Unknown".to_string()
        }
    }
}

// ===== Sub Task Definition =====

struct SubTask {
    id: i32,
    name: String,
    input_type: String,
    output_type: String,
    priority: i32,
    dependencies: Vec<i32>
}

trait SubTaskCl {
    fn clone(&self) -> SubTask;
}

impl SubTaskCl for SubTask {
    fn clone(&self) -> SubTask {
        SubTask {
            id: self.id,
            name: self.name.clone(),
            input_type: self.input_type.clone(),
            output_type: self.output_type.clone(),
            priority: self.priority,
            dependencies: self.dependencies.clone()
        }
    }
}

// ===== Task Constraint =====

struct TaskConstraints {
    memory_limit_mb: i32,
    timeout_sec: i32,
    max_parallel_tasks: i32
}

trait TaskConstraintsCl {
    fn clone(&self) -> TaskConstraints;
}

impl TaskConstraintsCl for TaskConstraints {
    fn clone(&self) -> TaskConstraints {
        TaskConstraints {
            memory_limit_mb: self.memory_limit_mb,
            timeout_sec: self.timeout_sec,
            max_parallel_tasks: self.max_parallel_tasks
        }
    }
}

// ===== Intent Breakdown =====

struct IntentBreakdown {
    original_intent: String,
    sub_tasks: Vec<SubTask>,
    dependencies: Vec<(i32, i32)>,
    constraints: TaskConstraints,
    confidence: f32,
    intent_type: String
}

trait IntentBreakdownCl {
    fn clone(&self) -> IntentBreakdown;
}

impl IntentBreakdownCl for IntentBreakdown {
    fn clone(&self) -> IntentBreakdown {
        let mut cloned_tasks = vec![];
        for i in 0..self.sub_tasks.len() {
            cloned_tasks.push(self.sub_tasks[i].clone());
        }
        let mut cloned_deps = vec![];
        for i in 0..self.dependencies.len() {
            let dep = self.dependencies[i];
            cloned_deps.push((dep.0, dep.1));
        }

        IntentBreakdown {
            original_intent: self.original_intent.clone(),
            sub_tasks: cloned_tasks,
            dependencies: cloned_deps,
            constraints: self.constraints.clone(),
            confidence: self.confidence,
            intent_type: self.intent_type.clone()
        }
    }
}

// ===== Intent Architect =====

struct IntentArchitect {
    agent_id: String,
    breakdown_history: Vec<IntentBreakdown>
}

impl IntentArchitect {
    fn new(agent_id: String) -> IntentArchitect {
        IntentArchitect {
            agent_id: agent_id,
            breakdown_history: vec![]
        }
    }

    fn detect_intent_type(&self, input: String) -> IntentType {
        let lower = input.clone();

        if lower.contains("더하기") || lower.contains("add") || lower.contains("합") {
            return IntentType::Compute;
        }
        if lower.contains("변환") || lower.contains("transform") || lower.contains("convert") {
            return IntentType::Transform;
        }
        if lower.contains("필터") || lower.contains("filter") || lower.contains("선택") {
            return IntentType::Filter;
        }
        if lower.contains("집계") || lower.contains("aggregate") || lower.contains("합계") {
            return IntentType::Aggregate;
        }
        if lower.contains("파일") || lower.contains("file") || lower.contains("입출력") {
            return IntentType::IO;
        }
        if lower.contains("반복") || lower.contains("loop") || lower.contains("제어") {
            return IntentType::Control;
        }
        if lower.contains("검증") || lower.contains("validate") || lower.contains("확인") {
            return IntentType::Validate;
        }
        if lower.contains("포맷") || lower.contains("format") || lower.contains("형식") {
            return IntentType::Format;
        }

        IntentType::Unknown
    }

    fn decompose_intent(&mut self, input: String) -> IntentBreakdown {
        let intent_type = self.detect_intent_type(input.clone());
        let intent_type_str = match intent_type {
            IntentType::Compute => "Compute".to_string(),
            IntentType::Transform => "Transform".to_string(),
            IntentType::Filter => "Filter".to_string(),
            IntentType::Aggregate => "Aggregate".to_string(),
            IntentType::IO => "IO".to_string(),
            IntentType::Control => "Control".to_string(),
            IntentType::Validate => "Validate".to_string(),
            IntentType::Format => "Format".to_string(),
            IntentType::Unknown => "Unknown".to_string()
        };

        let mut sub_tasks = vec![];
        let mut dependencies = vec![];

        // 기본 분해: 입력 → 처리 → 출력
        let task1 = SubTask {
            id: 1,
            name: "input".to_string(),
            input_type: "String".to_string(),
            output_type: "Data".to_string(),
            priority: 1,
            dependencies: vec![]
        };
        sub_tasks.push(task1);

        let task2 = SubTask {
            id: 2,
            name: intent_type_str.clone(),
            input_type: "Data".to_string(),
            output_type: "Data".to_string(),
            priority: 2,
            dependencies: vec![1]
        };
        sub_tasks.push(task2);

        let task3 = SubTask {
            id: 3,
            name: "output".to_string(),
            input_type: "Data".to_string(),
            output_type: "Result".to_string(),
            priority: 3,
            dependencies: vec![2]
        };
        sub_tasks.push(task3);

        // 의존성 관계
        dependencies.push((1, 2));
        dependencies.push((2, 3));

        let constraints = TaskConstraints {
            memory_limit_mb: 100,
            timeout_sec: 30,
            max_parallel_tasks: 2
        };

        let breakdown = IntentBreakdown {
            original_intent: input,
            sub_tasks: sub_tasks,
            dependencies: dependencies,
            constraints: constraints,
            confidence: 0.92f32,
            intent_type: intent_type_str
        };

        self.breakdown_history.push(breakdown.clone());
        breakdown
    }

    fn extract_parameters(&self, input: String) -> Vec<String> {
        let mut params = vec![];
        let words: Vec<String> = input.split(" ").map(|w| w.to_string()).collect();

        for i in 0..words.len() {
            let w = &words[i];
            if w.contains("0") || w.contains("1") || w.contains("2") ||
               w.contains("3") || w.contains("4") || w.contains("5") ||
               w.contains("6") || w.contains("7") || w.contains("8") ||
               w.contains("9") {
                params.push(w.clone());
            }
        }
        params
    }

    fn get_history_size(&self) -> i32 {
        self.breakdown_history.len() as i32
    }

    fn estimate_execution_time(&self, breakdown: IntentBreakdown) -> i32 {
        let task_count = breakdown.sub_tasks.len() as i32;
        let base_time = 100i32;
        base_time * task_count
    }
}

// ===== Public API =====

fn create_intent_architect() -> IntentArchitect {
    IntentArchitect::new("intent-architect".to_string())
}

fn decompose_user_intent(input: String) -> IntentBreakdown {
    let mut architect = create_intent_architect();
    architect.decompose_intent(input)
}

fn process_intent_breakdown(breakdown: IntentBreakdown) -> AgentMessage {
    AgentMessage {
        sender_id: "intent-architect".to_string(),
        receiver_id: "graph-orchestrator".to_string(),
        message_type: "RequestExecutionPlan".to_string(),
        payload: breakdown.original_intent.clone(),
        timestamp: 1000000i64,
        priority: 10
    }
}

