// Phase 4: Graph Orchestrator Agent
// 서브 태스크를 DAG로 변환하고 실행 순서 결정

use crate::phase4::intent_architect::*;
use crate::phase4::agent_framework::*;

// ===== Execution Node =====

struct ExecutionNode {
    id: i32,
    task_name: String,
    estimated_time_ms: i32,
    is_critical: bool
}

trait ExecutionNodeCl {
    fn clone(&self) -> ExecutionNode;
}

impl ExecutionNodeCl for ExecutionNode {
    fn clone(&self) -> ExecutionNode {
        ExecutionNode {
            id: self.id,
            task_name: self.task_name.clone(),
            estimated_time_ms: self.estimated_time_ms,
            is_critical: self.is_critical
        }
    }
}

// ===== Execution Edge =====

struct ExecutionEdge {
    from_id: i32,
    to_id: i32,
    weight: i32
}

trait ExecutionEdgeCl {
    fn clone(&self) -> ExecutionEdge;
}

impl ExecutionEdgeCl for ExecutionEdge {
    fn clone(&self) -> ExecutionEdge {
        ExecutionEdge {
            from_id: self.from_id,
            to_id: self.to_id,
            weight: self.weight
        }
    }
}

// ===== Execution Phase (병렬 실행 가능 구간) =====

struct ExecutionPhase {
    phase_id: i32,
    task_ids: Vec<i32>,
    can_parallel: bool
}

trait ExecutionPhaseCl {
    fn clone(&self) -> ExecutionPhase;
}

impl ExecutionPhaseCl for ExecutionPhase {
    fn clone(&self) -> ExecutionPhase {
        let mut cloned_ids = vec![];
        for i in 0..self.task_ids.len() {
            cloned_ids.push(self.task_ids[i]);
        }
        ExecutionPhase {
            phase_id: self.phase_id,
            task_ids: cloned_ids,
            can_parallel: self.can_parallel
        }
    }
}

// ===== Execution Graph =====

struct ExecutionGraph {
    nodes: Vec<ExecutionNode>,
    edges: Vec<ExecutionEdge>,
    phases: Vec<ExecutionPhase>,
    critical_path: Vec<i32>,
    estimated_time_ms: i32
}

trait ExecutionGraphCl {
    fn clone(&self) -> ExecutionGraph;
}

impl ExecutionGraphCl for ExecutionGraph {
    fn clone(&self) -> ExecutionGraph {
        let mut cloned_nodes = vec![];
        for i in 0..self.nodes.len() {
            cloned_nodes.push(self.nodes[i].clone());
        }
        let mut cloned_edges = vec![];
        for i in 0..self.edges.len() {
            cloned_edges.push(self.edges[i].clone());
        }
        let mut cloned_phases = vec![];
        for i in 0..self.phases.len() {
            cloned_phases.push(self.phases[i].clone());
        }
        let mut cloned_path = vec![];
        for i in 0..self.critical_path.len() {
            cloned_path.push(self.critical_path[i]);
        }

        ExecutionGraph {
            nodes: cloned_nodes,
            edges: cloned_edges,
            phases: cloned_phases,
            critical_path: cloned_path,
            estimated_time_ms: self.estimated_time_ms
        }
    }
}

// ===== Graph Orchestrator =====

struct GraphOrchestrator {
    agent_id: String,
    graph_history: Vec<ExecutionGraph>
}

impl GraphOrchestrator {
    fn new(agent_id: String) -> GraphOrchestrator {
        GraphOrchestrator {
            agent_id: agent_id,
            graph_history: vec![]
        }
    }

    fn build_dag(&mut self, breakdown: IntentBreakdown) -> ExecutionGraph {
        let mut nodes = vec![];
        let mut edges = vec![];
        let mut phases = vec![];

        // 노드 생성
        for i in 0..breakdown.sub_tasks.len() {
            let task = &breakdown.sub_tasks[i];
            let node = ExecutionNode {
                id: task.id,
                task_name: task.name.clone(),
                estimated_time_ms: 100,
                is_critical: task.priority == 1 || task.priority == 2
            };
            nodes.push(node);
        }

        // 엣지 생성
        for i in 0..breakdown.dependencies.len() {
            let dep = breakdown.dependencies[i];
            let edge = ExecutionEdge {
                from_id: dep.0,
                to_id: dep.1,
                weight: 1
            };
            edges.push(edge);
        }

        // Phase 계산: 의존성 없는 작업들을 그룹화
        for i in 0..nodes.len() {
            let node = &nodes[i];
            let phase = ExecutionPhase {
                phase_id: i as i32,
                task_ids: vec![node.id],
                can_parallel: i > 0
            };
            phases.push(phase);
        }

        // 크리티컬 경로: 모든 노드 순서대로 (선형이므로)
        let mut critical_path = vec![];
        for i in 0..nodes.len() {
            critical_path.push((i + 1) as i32);
        }

        let estimated_time = nodes.len() as i32 * 100;

        let graph = ExecutionGraph {
            nodes: nodes,
            edges: edges,
            phases: phases,
            critical_path: critical_path,
            estimated_time_ms: estimated_time
        };

        self.graph_history.push(graph.clone());
        graph
    }

    fn identify_parallel_segments(&self, graph: ExecutionGraph) -> Vec<Vec<i32>> {
        let mut segments = vec![];

        for i in 0..graph.phases.len() {
            let phase = &graph.phases[i];
            if phase.can_parallel {
                segments.push(phase.task_ids.clone());
            }
        }

        segments
    }

    fn calculate_critical_path_time(&self, graph: ExecutionGraph) -> i32 {
        let mut total_time = 0i32;
        for i in 0..graph.nodes.len() {
            total_time = total_time + graph.nodes[i].estimated_time_ms;
        }
        total_time
    }

    fn get_graph_complexity(&self, graph: ExecutionGraph) -> f32 {
        let node_count = graph.nodes.len() as f32;
        let edge_count = graph.edges.len() as f32;
        (edge_count + 1.0f32) / (node_count + 1.0f32)
    }

    fn get_history_size(&self) -> i32 {
        self.graph_history.len() as i32
    }
}

// ===== Public API =====

fn create_graph_orchestrator() -> GraphOrchestrator {
    GraphOrchestrator::new("graph-orchestrator".to_string())
}

fn orchestrate_execution(breakdown: IntentBreakdown) -> ExecutionGraph {
    let mut orchestrator = create_graph_orchestrator();
    orchestrator.build_dag(breakdown)
}

fn process_execution_graph(graph: ExecutionGraph) -> AgentMessage {
    AgentMessage {
        sender_id: "graph-orchestrator".to_string(),
        receiver_id: "code-generator".to_string(),
        message_type: "RequestCodeGeneration".to_string(),
        payload: graph.estimated_time_ms.to_string(),
        timestamp: 1000001i64,
        priority: 9
    }
}

