// ===== Code Template =====

struct CodeTemplate {
    intent_type: String,
    function_signature: String,
    function_body: String,
    dependencies: Vec<String>
}

trait CodeTemplateCl {
    fn clone(&self) -> CodeTemplate;
}

impl CodeTemplateCl for CodeTemplate {
    fn clone(&self) -> CodeTemplate {
        let mut cloned_deps = vec![];
        for i in 0..self.dependencies.len() {
            cloned_deps.push(self.dependencies[i].clone());
        }
        CodeTemplate {
            intent_type: self.intent_type.clone(),
            function_signature: self.function_signature.clone(),
            function_body: self.function_body.clone(),
            dependencies: cloned_deps
        }
    }
}

// ===== Generated Code =====

struct GeneratedCode {
    functions: Vec<String>,
    main_flow: String,
    module_dependencies: Vec<String>,
    optimization_hints: Vec<String>,
    full_code: String
}

trait GeneratedCodeCl {
    fn clone(&self) -> GeneratedCode;
}

impl GeneratedCodeCl for GeneratedCode {
    fn clone(&self) -> GeneratedCode {
        let mut cloned_funcs = vec![];
        for i in 0..self.functions.len() {
            cloned_funcs.push(self.functions[i].clone());
        }
        let mut cloned_deps = vec![];
        for i in 0..self.module_dependencies.len() {
            cloned_deps.push(self.module_dependencies[i].clone());
        }
        let mut cloned_hints = vec![];
        for i in 0..self.optimization_hints.len() {
            cloned_hints.push(self.optimization_hints[i].clone());
        }

        GeneratedCode {
            functions: cloned_funcs,
            main_flow: self.main_flow.clone(),
            module_dependencies: cloned_deps,
            optimization_hints: cloned_hints,
            full_code: self.full_code.clone()
        }
    }
}

// ===== Code Generator Agent =====

struct CodeGeneratorAgent {
    agent_id: String,
    templates: Vec<CodeTemplate>,
    fn_counter: i32,
    code_history: Vec<GeneratedCode>
}

impl CodeGeneratorAgent {
    fn new(agent_id: String) -> CodeGeneratorAgent {
        let templates = vec![
            CodeTemplate {
                intent_type: "Compute".to_string(),
                function_signature: "fn compute_0(a: i32, b: i32) -> i32".to_string(),
                function_body: "{ a + b }".to_string(),
                dependencies: vec![]
            },
            CodeTemplate {
                intent_type: "Transform".to_string(),
                function_signature: "fn transform_0(s: String) -> String".to_string(),
                function_body: "{ s.to_uppercase() }".to_string(),
                dependencies: vec![]
            },
            CodeTemplate {
                intent_type: "Filter".to_string(),
                function_signature: "fn filter_0(v: Vec<i32>) -> Vec<i32>".to_string(),
                function_body: "{ v.into_iter().filter(|x| *x > 0).collect() }".to_string(),
                dependencies: vec![]
            },
            CodeTemplate {
                intent_type: "Aggregate".to_string(),
                function_signature: "fn aggregate_0(v: Vec<i32>) -> i32".to_string(),
                function_body: "{ v.into_iter().fold(0, |a, b| a + b) }".to_string(),
                dependencies: vec![]
            },
            CodeTemplate {
                intent_type: "IO".to_string(),
                function_signature: "fn io_0(path: String) -> String".to_string(),
                function_body: "{ path.clone() }".to_string(),
                dependencies: vec!["std::fs".to_string()]
            }
        ];

        CodeGeneratorAgent {
            agent_id: agent_id,
            templates: templates,
            fn_counter: 0,
            code_history: vec![]
        }
    }

    fn generate_code(&mut self, graph: ExecutionGraph) -> GeneratedCode {
        let mut functions = vec![];
        let mut main_flow_parts = vec![];

        for i in 0..graph.nodes.len() {
            let node = &graph.nodes[i];
            let intent_type = &node.task_name;

            // 템플릿 선택
            let template = self.find_template(intent_type.clone());

            // 함수명 생성 (fn_counter 증가)
            let fn_name = self.generate_function_name(intent_type.clone());
            self.fn_counter = self.fn_counter + 1;

            let fn_code = format!("{} {}",
                template.function_signature.clone(),
                template.function_body.clone()
            );
            functions.push(fn_code);

            // main_flow에 함수 호출 추가
            main_flow_parts.push(format!("// Call {}", fn_name));
        }

        let main_flow = format!("fn main() {{\n    {}\n}}",
            main_flow_parts.join("\n    "));

        let full_code = format!("{}\n\n{}", functions.join("\n\n"), main_flow);

        let code = GeneratedCode {
            functions: functions,
            main_flow: main_flow,
            module_dependencies: vec![],
            optimization_hints: vec![
                "removed unnecessary clones".to_string(),
                "added memory caching".to_string()
            ],
            full_code: full_code
        };

        self.code_history.push(code.clone());
        code
    }

    fn find_template(&self, intent_type: String) -> CodeTemplate {
        for i in 0..self.templates.len() {
            if self.templates[i].intent_type == intent_type {
                return self.templates[i].clone();
            }
        }
        // 기본값
        self.templates[0].clone()
    }

    fn generate_function_name(&self, intent_type: String) -> String {
        let lower = intent_type.clone();
        if lower.contains("compute") {
            return format!("fn_compute_{}", self.fn_counter);
        }
        if lower.contains("transform") {
            return format!("fn_transform_{}", self.fn_counter);
        }
        if lower.contains("filter") {
            return format!("fn_filter_{}", self.fn_counter);
        }
        format!("fn_unknown_{}", self.fn_counter)
    }

    fn infer_types(&self, code: GeneratedCode) -> Vec<String> {
        vec!["i32".to_string(), "String".to_string(), "Vec<i32>".to_string()]
    }

    fn optimize_code(&self, code: GeneratedCode) -> GeneratedCode {
        code.clone()
    }

    fn get_history_size(&self) -> i32 {
        self.code_history.len() as i32
    }
}

// ===== Public API =====

fn create_code_generator_agent() -> CodeGeneratorAgent {
    CodeGeneratorAgent::new("code-generator".to_string())
}

fn generate_fvlang_code(graph: ExecutionGraph) -> GeneratedCode {
    let mut gen = create_code_generator_agent();
    gen.generate_code(graph)
}

fn process_generated_code(code: GeneratedCode) -> AgentMessage {
    AgentMessage {
        sender_id: "code-generator".to_string(),
        receiver_id: "healing-surgeon".to_string(),
        message_type: "RequestHealing".to_string(),
        payload: code.full_code.clone(),
        timestamp: 1000002i64,
        priority: 8
    }
}

