// Phase 4 Week 1 Tests: Agent Framework + Intent Architect + Graph Orchestrator + Code Generator
// 40개 테스트 (Framework 5 + Intent 10 + Graph 8 + CodeGen 10 + Integration 7)

use crate::phase4::agent_framework::*;
use crate::phase4::intent_architect::*;
use crate::phase4::graph_orchestrator::*;
use crate::phase4::code_generator_agent::*;

// ===== PART A: Agent Framework Tests (5개) =====

test "agent_creation" {
    let agent = create_agent("agent-1".to_string(), "compute".to_string());
    assert agent.agent_id == "agent-1".to_string();
}

test "agent_status_change" {
    let mut agent = create_agent("agent-1".to_string(), "compute".to_string());
    agent.update_status(AgentStatus::Processing);
    assert agent.get_status() == "PROCESSING".to_string();
}

test "message_bus_creation" {
    let bus = create_message_bus();
    assert bus.get_queue_size() == 0;
}

test "message_bus_enqueue" {
    let mut bus = create_message_bus();
    let msg = AgentMessage {
        sender_id: "a".to_string(),
        receiver_id: "b".to_string(),
        message_type: "test".to_string(),
        payload: "{}".to_string(),
        timestamp: 1000000i64,
        priority: 1
    };
    bus.enqueue_message(msg);
    assert bus.get_queue_size() == 1;
}

test "agent_registry_count" {
    let mut registry = create_agent_registry();
    let agent = create_agent("agent-1".to_string(), "compute".to_string());
    registry.register_agent(agent);
    assert registry.get_agent_count() == 1;
}

// ===== PART B: Intent Architect Tests (10개) =====

test "intent_architect_creation" {
    let architect = create_intent_architect();
    assert architect.agent_id == "intent-architect".to_string();
}

test "intent_type_detection_compute" {
    let architect = create_intent_architect();
    let intent = architect.detect_intent_type("더하기".to_string());
    match intent {
        IntentType::Compute => assert true,
        _ => assert false
    }
}

test "intent_type_detection_filter" {
    let architect = create_intent_architect();
    let intent = architect.detect_intent_type("필터".to_string());
    match intent {
        IntentType::Filter => assert true,
        _ => assert false
    }
}

test "intent_decompose_basic" {
    let breakdown = decompose_user_intent("더하기".to_string());
    assert breakdown.sub_tasks.len() == 3;
}

test "intent_decompose_dependencies" {
    let breakdown = decompose_user_intent("계산".to_string());
    assert breakdown.dependencies.len() == 2;
}

test "intent_decompose_constraints" {
    let breakdown = decompose_user_intent("작업".to_string());
    assert breakdown.constraints.memory_limit_mb == 100;
}

test "intent_decompose_confidence" {
    let breakdown = decompose_user_intent("테스트".to_string());
    assert breakdown.confidence > 0.9f32;
}

test "intent_parameter_extraction" {
    let architect = create_intent_architect();
    let params = architect.extract_parameters("더하기 5 10".to_string());
    assert params.len() > 0;
}

test "intent_execution_time_estimation" {
    let architect = create_intent_architect();
    let breakdown = architect.decompose_intent("작업".to_string());
    let time = architect.estimate_execution_time(breakdown);
    assert time > 0;
}

test "intent_history_tracking" {
    let mut architect = create_intent_architect();
    architect.decompose_intent("첫번째".to_string());
    architect.decompose_intent("두번째".to_string());
    assert architect.get_history_size() == 2;
}

// ===== PART C: Graph Orchestrator Tests (8개) =====

test "graph_orchestrator_creation" {
    let orchestrator = create_graph_orchestrator();
    assert orchestrator.agent_id == "graph-orchestrator".to_string();
}

test "graph_dag_building" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.nodes.len() == 3;
}

test "graph_edges_creation" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.edges.len() > 0;
}

test "graph_phases_identification" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.phases.len() == 3;
}

test "graph_critical_path_calculation" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.critical_path.len() == 3;
}

test "graph_estimated_time" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.estimated_time_ms > 0;
}

test "graph_complexity_calculation" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    let orchestrator = create_graph_orchestrator();
    let complexity = orchestrator.get_graph_complexity(graph);
    assert complexity >= 0.0f32;
}

test "graph_history_tracking" {
    let mut orchestrator = create_graph_orchestrator();
    let breakdown1 = decompose_user_intent("첫번째".to_string());
    let breakdown2 = decompose_user_intent("두번째".to_string());
    orchestrator.build_dag(breakdown1);
    orchestrator.build_dag(breakdown2);
    assert orchestrator.get_history_size() == 2;
}

// ===== PART D: Code Generator Tests (10개) =====

test "code_generator_creation" {
    let gen = create_code_generator_agent();
    assert gen.agent_id == "code-generator".to_string();
}

test "code_generator_template_count" {
    let gen = create_code_generator_agent();
    assert gen.templates.len() == 5;
}

test "code_generation_basic" {
    let breakdown = decompose_user_intent("계산".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    assert code.functions.len() > 0;
}

test "code_generation_functions" {
    let breakdown = decompose_user_intent("변환".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    assert code.functions.len() == 3;
}

test "code_generation_main_flow" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    assert code.main_flow.contains("main");
}

test "code_generation_full_code" {
    let breakdown = decompose_user_intent("작업".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    assert code.full_code.len() > 0;
}

test "code_generation_optimization_hints" {
    let breakdown = decompose_user_intent("최적화".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    assert code.optimization_hints.len() >= 2;
}

test "code_type_inference" {
    let gen = create_code_generator_agent();
    let breakdown = decompose_user_intent("타입".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    let types = gen.infer_types(code);
    assert types.len() > 0;
}

test "code_uniqueness" {
    let breakdown = decompose_user_intent("고유".to_string());
    let graph = orchestrate_execution(breakdown);
    let code1 = generate_fvlang_code(graph.clone());
    let code2 = generate_fvlang_code(graph.clone());
    // 함수명이 증가해야 함
    assert code1.functions.len() == code2.functions.len();
}

test "code_history_tracking" {
    let mut gen = create_code_generator_agent();
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    gen.generate_code(graph.clone());
    gen.generate_code(graph.clone());
    assert gen.get_history_size() == 2;
}

// ===== PART E: Integration Tests (7개) =====

test "e2e_intent_to_graph" {
    let breakdown = decompose_user_intent("전체 테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.nodes.len() > 0;
    assert graph.edges.len() >= 0;
}

test "e2e_graph_to_code" {
    let breakdown = decompose_user_intent("전체 테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    assert code.full_code.len() > 0;
}

test "e2e_message_flow" {
    let breakdown = decompose_user_intent("메시지".to_string());
    let msg1 = process_intent_breakdown(breakdown.clone());
    assert msg1.message_type == "RequestExecutionPlan".to_string();

    let graph = orchestrate_execution(breakdown);
    let msg2 = process_execution_graph(graph.clone());
    assert msg2.message_type == "RequestCodeGeneration".to_string();

    let code = generate_fvlang_code(graph);
    let msg3 = process_generated_code(code);
    assert msg3.message_type == "RequestHealing".to_string();
}

test "e2e_agent_communication" {
    let mut bus = create_message_bus();
    let breakdown = decompose_user_intent("통신".to_string());
    let msg = process_intent_breakdown(breakdown);
    bus.enqueue_message(msg);
    assert bus.get_queue_size() == 1;
}

test "e2e_performance_under_threshold" {
    let breakdown = decompose_user_intent("성능".to_string());
    let graph = orchestrate_execution(breakdown);
    assert graph.estimated_time_ms < 1000;
}

test "e2e_code_complexity_measure" {
    let breakdown = decompose_user_intent("복잡도".to_string());
    let graph = orchestrate_execution(breakdown);
    let orchestrator = create_graph_orchestrator();
    let complexity = orchestrator.get_graph_complexity(graph);
    assert complexity < 1.0f32;
}

test "e2e_pipeline_completeness" {
    let breakdown = decompose_user_intent("완전성".to_string());
    assert breakdown.sub_tasks.len() > 0;
    assert breakdown.dependencies.len() >= 0;
    assert breakdown.constraints.memory_limit_mb > 0;
    assert breakdown.confidence > 0.0f32;
}

