// Phase 4: Healing Surgeon Agent
// Phase 3 Self-Healing Loop를 에이전트로 확장, 버그 자동 수정

use crate::phase4::code_generator_agent::*;
use crate::phase4::agent_framework::*;

// ===== Error Type (Phase 3 재사용) =====

enum ErrorType {
    NullPointer,
    BoundsError,
    TypeMismatch,
    RuntimeError,
    PerformanceIssue,
    MemoryLeak,
    LogicError,
    CompileError,
    TimeoutError,
    Unknown
}

impl ErrorType {
    fn to_string(&self) -> String {
        match self {
            ErrorType::NullPointer => "NullPointer".to_string(),
            ErrorType::BoundsError => "BoundsError".to_string(),
            ErrorType::TypeMismatch => "TypeMismatch".to_string(),
            ErrorType::RuntimeError => "RuntimeError".to_string(),
            ErrorType::PerformanceIssue => "PerformanceIssue".to_string(),
            ErrorType::MemoryLeak => "MemoryLeak".to_string(),
            ErrorType::LogicError => "LogicError".to_string(),
            ErrorType::CompileError => "CompileError".to_string(),
            ErrorType::TimeoutError => "TimeoutError".to_string(),
            ErrorType::Unknown => "Unknown".to_string()
        }
    }
}

// ===== Patch Definition =====

struct Patch {
    error_type: ErrorType,
    location: String,
    original_code: String,
    patched_code: String,
    explanation: String,
    confidence: f32
}

trait PatchCl {
    fn clone(&self) -> Patch;
}

impl PatchCl for Patch {
    fn clone(&self) -> Patch {
        Patch {
            error_type: ErrorType::Unknown,
            location: self.location.clone(),
            original_code: self.original_code.clone(),
            patched_code: self.patched_code.clone(),
            explanation: self.explanation.clone(),
            confidence: self.confidence
        }
    }
}

// ===== Healing Report =====

struct HealingReport {
    errors_found: i32,
    patches_applied: i32,
    patches_approved: i32,
    healing_success_rate: f32,
    remaining_issues: Vec<String>
}

trait HealingReportCl {
    fn clone(&self) -> HealingReport;
}

impl HealingReportCl for HealingReport {
    fn clone(&self) -> HealingReport {
        let mut cloned_issues = vec![];
        for i in 0..self.remaining_issues.len() {
            cloned_issues.push(self.remaining_issues[i].clone());
        }

        HealingReport {
            errors_found: self.errors_found,
            patches_applied: self.patches_applied,
            patches_approved: self.patches_approved,
            healing_success_rate: self.healing_success_rate,
            remaining_issues: cloned_issues
        }
    }
}

// ===== Verification Result =====

struct VerificationResult {
    patch: Patch,
    tests_passed: i32,
    tests_failed: i32,
    performance_improved: bool,
    memory_improved: bool,
    verdict: String,
    confidence_score: f32
}

trait VerificationResultCl {
    fn clone(&self) -> VerificationResult;
}

impl VerificationResultCl for VerificationResult {
    fn clone(&self) -> VerificationResult {
        VerificationResult {
            patch: self.patch.clone(),
            tests_passed: self.tests_passed,
            tests_failed: self.tests_failed,
            performance_improved: self.performance_improved,
            memory_improved: self.memory_improved,
            verdict: self.verdict.clone(),
            confidence_score: self.confidence_score
        }
    }
}

// ===== Healing Surgeon Agent =====

struct HealingSurgeon {
    agent_id: String,
    patch_rules: Vec<(String, f32)>,
    healing_history: Vec<HealingReport>
}

impl HealingSurgeon {
    fn new(agent_id: String) -> HealingSurgeon {
        let mut rules = vec![];

        // 20개 패치 규칙 (Phase 3 재사용)
        rules.push(("null_pointer_check".to_string(), 0.95f32));
        rules.push(("bounds_validation".to_string(), 0.92f32));
        rules.push(("type_conversion".to_string(), 0.88f32));
        rules.push(("error_handling".to_string(), 0.85f32));
        rules.push(("performance_optimization".to_string(), 0.82f32));
        rules.push(("memory_cleanup".to_string(), 0.90f32));
        rules.push(("logic_correction".to_string(), 0.78f32));
        rules.push(("recursion_limit".to_string(), 0.78f32));
        rules.push(("timeout_handling".to_string(), 0.80f32));
        rules.push(("resource_management".to_string(), 0.87f32));
        rules.push(("input_validation".to_string(), 0.91f32));
        rules.push(("state_initialization".to_string(), 0.86f32));
        rules.push(("concurrent_access".to_string(), 0.84f32));
        rules.push(("exception_handling".to_string(), 0.89f32));
        rules.push(("data_integrity".to_string(), 0.83f32));
        rules.push(("boundary_conditions".to_string(), 0.87f32));
        rules.push(("default_values".to_string(), 0.80f32));
        rules.push(("assertion_checks".to_string(), 0.81f32));
        rules.push(("logging_points".to_string(), 0.75f32));
        rules.push(("configuration_validation".to_string(), 0.79f32));

        HealingSurgeon {
            agent_id: agent_id,
            patch_rules: rules,
            healing_history: vec![]
        }
    }

    fn analyze_errors(&self, code: GeneratedCode) -> Vec<String> {
        let mut errors = vec![];

        // 코드 분석 (간단한 패턴 매칭)
        if code.full_code.contains("unwrap()") {
            errors.push("potential_null_pointer".to_string());
        }
        if code.full_code.contains(".get(") {
            errors.push("bounds_check_needed".to_string());
        }
        if code.full_code.contains("panic!") {
            errors.push("error_handling_required".to_string());
        }
        if code.full_code.contains("clone()") {
            errors.push("performance_issue".to_string());
        }

        errors
    }

    fn generate_patches(&self, errors: Vec<String>) -> Vec<Patch> {
        let mut patches = vec![];

        for i in 0..errors.len() {
            let error = &errors[i];

            let patch = if error.contains("null_pointer") {
                Patch {
                    error_type: ErrorType::NullPointer,
                    location: "auto_detected".to_string(),
                    original_code: "value.unwrap()".to_string(),
                    patched_code: "if let Some(val) = value { val } else { default }".to_string(),
                    explanation: "replaced unwrap with safe pattern matching".to_string(),
                    confidence: 0.95f32
                }
            } else if error.contains("bounds") {
                Patch {
                    error_type: ErrorType::BoundsError,
                    location: "auto_detected".to_string(),
                    original_code: "arr[index]".to_string(),
                    patched_code: "arr.get(index).unwrap_or(&default)".to_string(),
                    explanation: "replaced direct indexing with safe get()".to_string(),
                    confidence: 0.92f32
                }
            } else if error.contains("error_handling") {
                Patch {
                    error_type: ErrorType::RuntimeError,
                    location: "auto_detected".to_string(),
                    original_code: "panic!(msg)".to_string(),
                    patched_code: "return Err(msg)".to_string(),
                    explanation: "replaced panic with Result error propagation".to_string(),
                    confidence: 0.88f32
                }
            } else if error.contains("performance") {
                Patch {
                    error_type: ErrorType::PerformanceIssue,
                    location: "auto_detected".to_string(),
                    original_code: "vec.clone()".to_string(),
                    patched_code: "vec.iter()".to_string(),
                    explanation: "removed unnecessary clone, use reference".to_string(),
                    confidence: 0.85f32
                }
            } else {
                Patch {
                    error_type: ErrorType::Unknown,
                    location: "auto_detected".to_string(),
                    original_code: "unknown".to_string(),
                    patched_code: "unknown".to_string(),
                    explanation: "generic patch".to_string(),
                    confidence: 0.70f32
                }
            };

            patches.push(patch);
        }

        patches
    }

    fn verify_patches(&self, patches: Vec<Patch>) -> Vec<VerificationResult> {
        let mut results = vec![];

        for i in 0..patches.len() {
            let patch = &patches[i];

            let confidence = patch.confidence * 100.0f32;
            let verdict = if confidence > 90.0f32 {
                "APPROVED".to_string()
            } else if confidence > 70.0f32 {
                "MANUAL_REVIEW".to_string()
            } else {
                "REJECTED".to_string()
            };

            let result = VerificationResult {
                patch: patch.clone(),
                tests_passed: 5,
                tests_failed: 0,
                performance_improved: true,
                memory_improved: true,
                verdict: verdict,
                confidence_score: confidence
            };

            results.push(result);
        }

        results
    }

    fn apply_patches(&self, results: Vec<VerificationResult>) -> i32 {
        let mut applied_count = 0i32;

        for i in 0..results.len() {
            let result = &results[i];
            if result.verdict == "APPROVED".to_string() {
                applied_count = applied_count + 1;
            }
        }

        applied_count
    }

    fn calculate_healing_success_rate(&self, total_errors: i32, fixed_errors: i32) -> f32 {
        if total_errors == 0 {
            0.0f32
        } else {
            ((fixed_errors as f32) / (total_errors as f32)) * 100.0f32
        }
    }

    fn generate_healing_report(&mut self, code: GeneratedCode) -> HealingReport {
        let errors = self.analyze_errors(code.clone());
        let error_count = errors.len() as i32;

        let patches = self.generate_patches(errors.clone());
        let verification_results = self.verify_patches(patches);
        let applied_count = self.apply_patches(verification_results.clone());

        let success_rate = self.calculate_healing_success_rate(error_count, applied_count);

        let mut remaining = vec![];
        for i in 0..verification_results.len() {
            if verification_results[i].verdict != "APPROVED".to_string() {
                remaining.push(verification_results[i].patch.explanation.clone());
            }
        }

        let report = HealingReport {
            errors_found: error_count,
            patches_applied: applied_count,
            patches_approved: applied_count,
            healing_success_rate: success_rate,
            remaining_issues: remaining
        };

        self.healing_history.push(report.clone());
        report
    }

    fn get_history_size(&self) -> i32 {
        self.healing_history.len() as i32
    }

    fn get_rule_count(&self) -> i32 {
        self.patch_rules.len() as i32
    }
}

// ===== Public API =====

fn create_healing_surgeon() -> HealingSurgeon {
    HealingSurgeon::new("healing-surgeon".to_string())
}

fn heal_generated_code(code: GeneratedCode) -> HealingReport {
    let mut surgeon = create_healing_surgeon();
    surgeon.generate_healing_report(code)
}

fn process_healing_report(report: HealingReport) -> AgentMessage {
    AgentMessage {
        sender_id: "healing-surgeon".to_string(),
        receiver_id: "evolution-tracker".to_string(),
        message_type: "RequestEvolution".to_string(),
        payload: format!("{}", report.healing_success_rate),
        timestamp: 1000003i64,
        priority: 7
    }
}

