            improvement_percentage: self.improvement_percentage
        }
    }
}

// ===== Updated Rule =====

struct UpdatedRule {
    rule_name: String,
    old_confidence: f32,
    new_confidence: f32,
    confidence_delta: f32
}

trait UpdatedRuleCl {
    fn clone(&self) -> UpdatedRule;
}

impl UpdatedRuleCl for UpdatedRule {
    fn clone(&self) -> UpdatedRule {
        UpdatedRule {
            rule_name: self.rule_name.clone(),
            old_confidence: self.old_confidence,
            new_confidence: self.new_confidence,
            confidence_delta: self.confidence_delta
        }
    }
}

// ===== Evolution Metrics =====

struct EvolutionMetrics {
    pattern_stats: Vec<PatternStats>,
    updated_rules: Vec<UpdatedRule>,
    learning_rate: f32,
    recommendations: Vec<String>,
    total_patterns_learned: i32
}

trait EvolutionMetricsCl {
    fn clone(&self) -> EvolutionMetrics;
}

impl EvolutionMetricsCl for EvolutionMetrics {
    fn clone(&self) -> EvolutionMetrics {
        let mut cloned_patterns = vec![];
        for i in 0..self.pattern_stats.len() {
            cloned_patterns.push(self.pattern_stats[i].clone());
        }
        let mut cloned_rules = vec![];
        for i in 0..self.updated_rules.len() {
            cloned_rules.push(self.updated_rules[i].clone());
        }
        let mut cloned_recs = vec![];
        for i in 0..self.recommendations.len() {
            cloned_recs.push(self.recommendations[i].clone());
        }

        EvolutionMetrics {
            pattern_stats: cloned_patterns,
            updated_rules: cloned_rules,
            learning_rate: self.learning_rate,
            recommendations: cloned_recs,
            total_patterns_learned: self.total_patterns_learned
        }
    }
}

// ===== Evolution Tracker Agent =====

struct EvolutionTracker {
    agent_id: String,
    pattern_database: Vec<PatternStats>,
    rule_confidence_map: Vec<(String, f32)>,
    learning_history: Vec<EvolutionMetrics>,
    total_healing_sessions: i32
}

impl EvolutionTracker {
    fn new(agent_id: String) -> EvolutionTracker {
        let mut patterns = vec![];

        // 초기 패턴 (Phase 3 + 확장)
        patterns.push(PatternStats {
            pattern_name: "null_pointer_safe_access".to_string(),
            success_rate: 0.95f32,
            applied_count: 0,
            improvement_percentage: 0.0f32
        });

        patterns.push(PatternStats {
            pattern_name: "bounds_check_get".to_string(),
            success_rate: 0.92f32,
            applied_count: 0,
            improvement_percentage: 0.0f32
        });

        patterns.push(PatternStats {
            pattern_name: "error_result_propagation".to_string(),
            success_rate: 0.88f32,
            applied_count: 0,
            improvement_percentage: 0.0f32
        });

        patterns.push(PatternStats {
            pattern_name: "performance_clone_removal".to_string(),
            success_rate: 0.85f32,
            applied_count: 0,
            improvement_percentage: 0.0f32
        });

        patterns.push(PatternStats {
            pattern_name: "memory_leak_prevention".to_string(),
            success_rate: 0.90f32,
            applied_count: 0,
            improvement_percentage: 0.0f32
        });

        let mut confidence_map = vec![];
        for i in 0..patterns.len() {
            confidence_map.push((patterns[i].pattern_name.clone(), patterns[i].success_rate));
        }

        EvolutionTracker {
            agent_id: agent_id,
            pattern_database: patterns,
            rule_confidence_map: confidence_map,
            learning_history: vec![],
            total_healing_sessions: 0
        }
    }

    fn extract_success_patterns(&self, report: HealingReport) -> Vec<PatternStats> {
        let mut patterns = vec![];

        // 성공률 기반 패턴 추출
        let success_rate = report.healing_success_rate / 100.0f32;

        if success_rate > 0.8f32 {
            patterns.push(PatternStats {
                pattern_name: "high_success_healing".to_string(),
                success_rate: success_rate,
                applied_count: report.patches_approved,
                improvement_percentage: (success_rate * 100.0f32) - 80.0f32
            });
        }

        patterns
    }

    fn update_rule_confidence(&mut self, report: HealingReport) -> Vec<UpdatedRule> {
        let mut updated_rules = vec![];

        for i in 0..self.rule_confidence_map.len() {
            let rule_name = self.rule_confidence_map[i].0.clone();
            let old_conf = self.rule_confidence_map[i].1;

            // 신뢰도 업데이트: 성공률 기반
            let success_factor = report.healing_success_rate / 100.0f32;
            let new_conf = (old_conf + success_factor) / 2.0f32;

            // 최댓값 0.98로 제한
            let capped_conf = if new_conf > 0.98f32 { 0.98f32 } else { new_conf };

            let delta = capped_conf - old_conf;

            updated_rules.push(UpdatedRule {
                rule_name: rule_name.clone(),
                old_confidence: old_conf,
                new_confidence: capped_conf,
                confidence_delta: delta
            });

            // 맵 업데이트
            self.rule_confidence_map[i].1 = capped_conf;
        }

        updated_rules
    }

    fn generate_recommendations(&self, metrics: EvolutionMetrics) -> Vec<String> {
        let mut recs = vec![];

        // 높은 학습률이면 계속 진행
        if metrics.learning_rate > 0.05f32 {
            recs.push("continue_aggressive_patching".to_string());
        }

        // 패턴이 5개 이상이면 최적화 권장
        if metrics.total_patterns_learned >= 5 {
            recs.push("optimize_pattern_matching".to_string());
        }

        // 규칙 신뢰도가 낮으면 리뷰 권장
        for i in 0..metrics.updated_rules.len() {
            if metrics.updated_rules[i].new_confidence < 0.75f32 {
                recs.push("review_low_confidence_rule".to_string());
            }
        }

        recs
    }

    fn calculate_learning_rate(&self, metrics: EvolutionMetrics) -> f32 {
        if metrics.pattern_stats.len() == 0 {
            0.0f32
        } else {
            let avg_improvement = {
                let mut sum = 0.0f32;
                for i in 0..metrics.pattern_stats.len() {
                    sum = sum + metrics.pattern_stats[i].improvement_percentage;
                }
                sum / (metrics.pattern_stats.len() as f32)
            };

            (avg_improvement / 100.0f32) * 0.1f32
        }
    }

    fn track_evolution(&mut self, report: HealingReport) -> EvolutionMetrics {
        self.total_healing_sessions = self.total_healing_sessions + 1;

        let patterns = self.extract_success_patterns(report.clone());
        let updated_rules = self.update_rule_confidence(report);

        let mut metrics = EvolutionMetrics {
            pattern_stats: patterns,
            updated_rules: updated_rules,
            learning_rate: 0.0f32,
            recommendations: vec![],
            total_patterns_learned: self.pattern_database.len() as i32
        };

        metrics.learning_rate = self.calculate_learning_rate(metrics.clone());
        metrics.recommendations = self.generate_recommendations(metrics.clone());

        self.learning_history.push(metrics.clone());
        metrics
    }

    fn get_history_size(&self) -> i32 {
        self.learning_history.len() as i32
    }

    fn get_pattern_count(&self) -> i32 {
        self.pattern_database.len() as i32
    }

    fn get_total_sessions(&self) -> i32 {
        self.total_healing_sessions
    }
}

// ===== Public API =====

fn create_evolution_tracker() -> EvolutionTracker {
    EvolutionTracker::new("evolution-tracker".to_string())
}

fn track_healing_evolution(report: HealingReport) -> EvolutionMetrics {
    let mut tracker = create_evolution_tracker();
    tracker.track_evolution(report)
}

fn process_evolution_metrics(metrics: EvolutionMetrics) -> AgentMessage {
    AgentMessage {
        sender_id: "evolution-tracker".to_string(),
        receiver_id: "orchestrator".to_string(),
        message_type: "FinalResult".to_string(),
        payload: format!("{}", metrics.learning_rate),
        timestamp: 1000004i64,
        priority: 6
    }
}

