    message_bus: MessageBus,
    agent_registry: AgentRegistry,
    workflow_history: Vec<WorkflowState>,
    total_executions: i32
}

impl AgentOrchestrator {
    fn new(orchestrator_id: String) -> AgentOrchestrator {
        let mut registry = create_agent_registry();

        // 5개 에이전트 등록
        registry.register_agent(create_agent("intent-architect".to_string(), "architect".to_string()));
        registry.register_agent(create_agent("graph-orchestrator".to_string(), "orchestrator".to_string()));
        registry.register_agent(create_agent("code-generator".to_string(), "generator".to_string()));
        registry.register_agent(create_agent("healing-surgeon".to_string(), "surgeon".to_string()));
        registry.register_agent(create_agent("evolution-tracker".to_string(), "tracker".to_string()));

        AgentOrchestrator {
            orchestrator_id: orchestrator_id,
            message_bus: create_message_bus(),
            agent_registry: registry,
            workflow_history: vec![],
            total_executions: 0
        }
    }

    fn execute_intent_architect(&mut self, user_intent: String) -> IntentBreakdown {
        let breakdown = decompose_user_intent(user_intent.clone());

        let msg = process_intent_breakdown(breakdown.clone());
        self.message_bus.enqueue_message(msg);
        self.message_bus.record_success();

        breakdown
    }

    fn execute_graph_orchestrator(&mut self, breakdown: IntentBreakdown) -> ExecutionGraph {
        let graph = orchestrate_execution(breakdown);

        let msg = process_execution_graph(graph.clone());
        self.message_bus.enqueue_message(msg);
        self.message_bus.record_success();

        graph
    }

    fn execute_code_generator(&mut self, graph: ExecutionGraph) -> GeneratedCode {
        let code = generate_fvlang_code(graph);

        let msg = process_generated_code(code.clone());
        self.message_bus.enqueue_message(msg);
        self.message_bus.record_success();

        code
    }

    fn execute_healing_surgeon(&mut self, code: GeneratedCode) -> HealingReport {
        let report = heal_generated_code(code);

        let msg = process_healing_report(report.clone());
        self.message_bus.enqueue_message(msg);
        self.message_bus.record_success();

        report
    }

    fn execute_evolution_tracker(&mut self, report: HealingReport) -> EvolutionMetrics {
        let metrics = track_healing_evolution(report);

        let msg = process_evolution_metrics(metrics.clone());
        self.message_bus.enqueue_message(msg);
        self.message_bus.record_success();

        metrics
    }

    fn run_full_pipeline(&mut self, user_intent: String) -> PipelineResult {
        self.total_executions = self.total_executions + 1;

        // Step 1: Intent Architect
        let breakdown = self.execute_intent_architect(user_intent.clone());

        let mut state = WorkflowState {
            current_step: "intent_architect".to_string(),
            intent_breakdown: Some(breakdown.clone()),
            execution_graph: None,
            generated_code: None,
            healing_report: None,
            evolution_metrics: None,
            status: "in_progress".to_string()
        };

        // Step 2: Graph Orchestrator
        let graph = self.execute_graph_orchestrator(breakdown);
        state.current_step = "graph_orchestrator".to_string();
        state.execution_graph = Some(graph.clone());

        // Step 3: Code Generator
        let code = self.execute_code_generator(graph);
        state.current_step = "code_generator".to_string();
        state.generated_code = Some(code.clone());

        // Step 4: Healing Surgeon
        let healing = self.execute_healing_surgeon(code.clone());
        state.current_step = "healing_surgeon".to_string();
        state.healing_report = Some(healing.clone());

        // Step 5: Evolution Tracker
        let evolution = self.execute_evolution_tracker(healing.clone());
        state.current_step = "evolution_tracker".to_string();
        state.evolution_metrics = Some(evolution.clone());
        state.status = "completed".to_string();

        self.workflow_history.push(state);

        let result = PipelineResult {
            success: true,
            user_intent: user_intent,
            generated_code: code.full_code,
            patches_applied: healing.patches_approved,
            healing_success_rate: healing.healing_success_rate,
            learning_rate: evolution.learning_rate,
            execution_time_ms: 600
        };

        result
    }

    fn get_message_delivery_rate(&self) -> f32 {
        self.message_bus.get_delivery_rate()
    }

    fn get_workflow_history_size(&self) -> i32 {
        self.workflow_history.len() as i32
    }

    fn get_total_executions(&self) -> i32 {
        self.total_executions
    }

    fn get_registered_agent_count(&self) -> i32 {
        self.agent_registry.get_agent_count()
    }
}

// ===== Public API =====

fn create_orchestrator() -> AgentOrchestrator {
    AgentOrchestrator::new("main-orchestrator".to_string())
}

fn run_agent_pipeline(user_intent: String) -> PipelineResult {
    let mut orchestrator = create_orchestrator();
    orchestrator.run_full_pipeline(user_intent)
}

fn get_pipeline_health(orchestrator: AgentOrchestrator) -> f32 {
    orchestrator.get_message_delivery_rate()
}

