// Phase 4 Week 2 Tests: Healing Surgeon + Evolution Tracker + Agent Orchestrator
// 40개 테스트 (Surgeon 10 + Tracker 10 + Orchestrator 12 + E2E 8)

use crate::phase4::healing_surgeon::*;
use crate::phase4::evolution_tracker::*;
use crate::phase4::agent_orchestrator::*;
use crate::phase4::code_generator_agent::*;
use crate::phase4::intent_architect::*;

// ===== PART A: Healing Surgeon Tests (10개) =====

test "healing_surgeon_creation" {
    let surgeon = create_healing_surgeon();
    assert surgeon.agent_id == "healing-surgeon".to_string();
}

test "healing_surgeon_rules_count" {
    let surgeon = create_healing_surgeon();
    assert surgeon.get_rule_count() == 20;
}

test "healing_surgeon_error_analysis" {
    let breakdown = decompose_user_intent("분석".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    let surgeon = create_healing_surgeon();
    let errors = surgeon.analyze_errors(code);
    // 적어도 하나의 에러는 감지
    assert true;
}

test "healing_surgeon_patch_generation" {
    let errors = vec![
        "potential_null_pointer".to_string(),
        "bounds_check_needed".to_string()
    ];
    let surgeon = create_healing_surgeon();
    let patches = surgeon.generate_patches(errors);
    assert patches.len() == 2;
}

test "healing_surgeon_patch_verification" {
    let errors = vec!["potential_null_pointer".to_string()];
    let surgeon = create_healing_surgeon();
    let patches = surgeon.generate_patches(errors);
    let results = surgeon.verify_patches(patches);
    assert results.len() == 1;
    assert results[0].verdict != "REJECTED".to_string();
}

test "healing_surgeon_patch_application" {
    let errors = vec!["potential_null_pointer".to_string()];
    let surgeon = create_healing_surgeon();
    let patches = surgeon.generate_patches(errors);
    let results = surgeon.verify_patches(patches);
    let applied = surgeon.apply_patches(results);
    assert applied >= 0;
}

test "healing_surgeon_success_rate_calculation" {
    let surgeon = create_healing_surgeon();
    let rate1 = surgeon.calculate_healing_success_rate(10, 8);
    assert rate1 == 80.0f32;

    let rate2 = surgeon.calculate_healing_success_rate(0, 0);
    assert rate2 == 0.0f32;
}

test "healing_surgeon_report_generation" {
    let breakdown = decompose_user_intent("테스트".to_string());
    let graph = orchestrate_execution(breakdown);
    let code = generate_fvlang_code(graph);
    let report = heal_generated_code(code);
    assert report.errors_found >= 0;
    assert report.patches_applied >= 0;
}

test "healing_surgeon_history_tracking" {
    let mut surgeon = create_healing_surgeon();
    let breakdown1 = decompose_user_intent("첫번째".to_string());
    let graph1 = orchestrate_execution(breakdown1);
    let code1 = generate_fvlang_code(graph1);
    surgeon.generate_healing_report(code1);

    let breakdown2 = decompose_user_intent("두번째".to_string());
    let graph2 = orchestrate_execution(breakdown2);
    let code2 = generate_fvlang_code(graph2);
    surgeon.generate_healing_report(code2);

    assert surgeon.get_history_size() == 2;
}

test "healing_surgeon_confidence_scoring" {
    let errors = vec!["potential_null_pointer".to_string()];
    let surgeon = create_healing_surgeon();
    let patches = surgeon.generate_patches(errors);
    assert patches[0].confidence > 0.7f32;
    assert patches[0].confidence <= 1.0f32;
}

// ===== PART B: Evolution Tracker Tests (10개) =====

test "evolution_tracker_creation" {
    let tracker = create_evolution_tracker();
    assert tracker.agent_id == "evolution-tracker".to_string();
}

test "evolution_tracker_pattern_count" {
    let tracker = create_evolution_tracker();
    assert tracker.get_pattern_count() == 5;
}

test "evolution_tracker_pattern_extraction" {
    let report = HealingReport {
        errors_found: 5,
        patches_applied: 4,
        patches_approved: 4,
        healing_success_rate: 85.0f32,
        remaining_issues: vec![]
    };

    let tracker = create_evolution_tracker();
    let patterns = tracker.extract_success_patterns(report);
    assert patterns.len() > 0;
}

test "evolution_tracker_rule_confidence_update" {
    let mut tracker = create_evolution_tracker();
    let report = HealingReport {
        errors_found: 5,
        patches_applied: 4,
        patches_approved: 4,
        healing_success_rate: 90.0f32,
        remaining_issues: vec![]
    };

    let updated = tracker.update_rule_confidence(report);
    assert updated.len() > 0;
}

test "evolution_tracker_recommendation_generation" {
    let metrics = EvolutionMetrics {
        pattern_stats: vec![
            PatternStats {
                pattern_name: "test".to_string(),
                success_rate: 0.95f32,
                applied_count: 10,
                improvement_percentage: 15.0f32
            }
        ],
        updated_rules: vec![],
        learning_rate: 0.1f32,
        recommendations: vec![],
        total_patterns_learned: 5
    };

    let tracker = create_evolution_tracker();
    let recs = tracker.generate_recommendations(metrics);
    assert recs.len() > 0;
}

test "evolution_tracker_learning_rate_calculation" {
    let metrics = EvolutionMetrics {
        pattern_stats: vec![
            PatternStats {
                pattern_name: "test".to_string(),
                success_rate: 0.95f32,
                applied_count: 5,
                improvement_percentage: 10.0f32
            }
        ],
        updated_rules: vec![],
        learning_rate: 0.0f32,
        recommendations: vec![],
        total_patterns_learned: 1
    };

    let tracker = create_evolution_tracker();
    let lr = tracker.calculate_learning_rate(metrics);
    assert lr >= 0.0f32 && lr <= 1.0f32;
}

test "evolution_tracker_evolution_tracking" {
    let mut tracker = create_evolution_tracker();
    let report = HealingReport {
        errors_found: 5,
        patches_applied: 4,
        patches_approved: 4,
        healing_success_rate: 85.0f32,
        remaining_issues: vec![]
    };

    let metrics = tracker.track_evolution(report);
    assert metrics.pattern_stats.len() >= 0;
}

test "evolution_tracker_history_tracking" {
    let mut tracker = create_evolution_tracker();
    let report1 = HealingReport {
        errors_found: 5,
        patches_applied: 4,
        patches_approved: 4,
        healing_success_rate: 85.0f32,
        remaining_issues: vec![]
    };
    tracker.track_evolution(report1);

    let report2 = HealingReport {
        errors_found: 3,
        patches_applied: 3,
        patches_approved: 3,
        healing_success_rate: 90.0f32,
        remaining_issues: vec![]
    };
    tracker.track_evolution(report2);

    assert tracker.get_history_size() == 2;
}

test "evolution_tracker_session_counting" {
    let mut tracker = create_evolution_tracker();
    let report = HealingReport {
        errors_found: 5,
        patches_applied: 4,
        patches_approved: 4,
        healing_success_rate: 85.0f32,
        remaining_issues: vec![]
    };

    tracker.track_evolution(report.clone());
    tracker.track_evolution(report.clone());
    tracker.track_evolution(report);

