// ===== Execution Trace =====

struct ExecutionTrace {
    step: i32,
    agent_name: String,
    input_type: String,
    output_type: String,
    duration_ms: i32,
    status: String
}

trait ExecutionTraceCl {
    fn clone(&self) -> ExecutionTrace;
}

impl ExecutionTraceCl for ExecutionTrace {
    fn clone(&self) -> ExecutionTrace {
        ExecutionTrace {
            step: self.step,
            agent_name: self.agent_name.clone(),
            input_type: self.input_type.clone(),
            output_type: self.output_type.clone(),
            duration_ms: self.duration_ms,
            status: self.status.clone()
        }
    }
}

// ===== Detailed Execution Report =====

struct DetailedExecutionReport {
    user_input: String,
    traces: Vec<ExecutionTrace>,
    total_time_ms: i32,
    success: bool,
    final_metrics: String
}

trait DetailedExecutionReportCl {
    fn clone(&self) -> DetailedExecutionReport;
}

impl DetailedExecutionReportCl for DetailedExecutionReport {
    fn clone(&self) -> DetailedExecutionReport {
        let mut cloned_traces = vec![];
        for i in 0..self.traces.len() {
            cloned_traces.push(self.traces[i].clone());
        }

        DetailedExecutionReport {
            user_input: self.user_input.clone(),
            traces: cloned_traces,
            total_time_ms: self.total_time_ms,
            success: self.success,
            final_metrics: self.final_metrics.clone()
        }
    }
}

