// Phase 4 실제 실행 데모 테스트

use crate::phase4::execution_demo::*;

test "execution_demo_creation" {
    let demo = create_execution_demo();
    assert demo.get_execution_count() == 0;
}

test "execution_demo_basic_pipeline" {
    let report = run_demo_pipeline("더하기".to_string());
    assert report.success == true;
    assert report.traces.len() == 5;
