    let report = run_demo_pipeline("테스트".to_string());
    let mut completed_count = 0i32;
    for i in 0..report.traces.len() {
        if report.traces[i].status == "COMPLETED".to_string() {
            completed_count = completed_count + 1;
        }
    }
    assert completed_count == 5;
}

test "execution_demo_timing" {
    let report = run_demo_pipeline("시간측정".to_string());
    assert report.total_time_ms > 0;
    assert report.total_time_ms < 1000;
}

