    let report = run_demo_pipeline("순서".to_string());
    assert report.traces[0].step == 1;
    assert report.traces[1].step == 2;
    assert report.traces[2].step == 3;
    assert report.traces[3].step == 4;
    assert report.traces[4].step == 5;
}

