// 5개 의도를 연쇄 실행하는 복잡한 시나리오

use crate::phase4::complex_scenario::*;

// ===== Engine Tests =====

test "complex_engine_creation" {
    let engine = create_complex_engine();
    assert engine.get_step_count() == 5;
}

test "complex_engine_scenario_execution" {
    let scenario = run_complex_scenario();
    assert scenario.execution_results.len() == 5;
}

test "complex_engine_all_steps_success" {
    let scenario = run_complex_scenario();
    let mut success_count = 0i32;
    for i in 0..scenario.execution_results.len() {
        if scenario.execution_results[i].success {
            success_count = success_count + 1;
        }
    }
    assert success_count == 5;
}

test "complex_engine_intents_captured" {
    let scenario = run_complex_scenario();
    assert scenario.user_intents.len() == 5;
    assert scenario.user_intents[0].contains("더하기");
    assert scenario.user_intents[1].contains("변환");
    assert scenario.user_intents[2].contains("필터");
    assert scenario.user_intents[3].contains("집계");
